        // Height adjustment system
        window.__heightAdjustment = {
            resizeObserver: null,
            mutationObserver: null,
            previousHeight: 0,
            checkInterval: null,
            
            measureHeight: function() {
                // Get the maximum height by checking multiple elements
                const bodyHeight = document.body.scrollHeight;
                const documentHeight = document.documentElement.scrollHeight;
                const maxHeight = Math.max(
                    bodyHeight,
                    documentHeight,
                    ...Array.from(document.body.children).map(el => el.scrollHeight)
                );
                
                if (maxHeight !== this.previousHeight) {
                    this.previousHeight = maxHeight;
                    window.parent.postMessage({
                        type: 'iframe-height',
                        height: Math.ceil(maxHeight)
                    }, '*');
                }
            },
            
            init: function() {
                // Create resize observer
                this.resizeObserver = new ResizeObserver((entries) => {
                    this.measureHeight();
                });

                // Create mutation observer
                this.mutationObserver = new MutationObserver((mutations) => {
                    this.measureHeight();
                });

                // Observe body and its children for resizes
                this.resizeObserver.observe(document.body);
                Array.from(document.body.children).forEach(child => {
                    this.resizeObserver.observe(child);
                });

                // Observe body for DOM mutations
                this.mutationObserver.observe(document.body, {
                    childList: true,
                    subtree: true,
                    attributes: true,
                    characterData: true
                });

                // Set up periodic check (as fallback)
                this.checkInterval = setInterval(() => this.measureHeight(), 1000);

                // Initial measurement
                this.measureHeight();

                // Add event listeners for dynamic content
                window.addEventListener('load', () => this.measureHeight());
                window.addEventListener('DOMContentLoaded', () => this.measureHeight());
                window.addEventListener('resize', () => this.measureHeight());

                // Handle dynamic content loading
                const originalFetch = window.fetch;
                window.fetch = async (...args) => {
                    const response = await originalFetch(...args);
                    setTimeout(() => this.measureHeight(), 100);
                    return response;
                };

                // Handle image loading
                document.addEventListener('load', (event) => {
                    if (event.target instanceof HTMLImageElement) {
                        this.measureHeight();
                    }
                }, true);
            },

            cleanup: function() {
                if (this.resizeObserver) this.resizeObserver.disconnect();
                if (this.mutationObserver) this.mutationObserver.disconnect();
                if (this.checkInterval) clearInterval(this.checkInterval);
            }
        };

        // Initialize after DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => window.__heightAdjustment.init());
        } else {
            window.__heightAdjustment.init();
        }
